  SELECT count(*) FROM validaciones_mes WHERE ts >= $1 AND ts < $2;
SET plan_cache_mode = force_generic_plan;
EXPLAIN (COSTS OFF) EXECUTE por_rango('2026-03-01', '2026-04-01');
RESET plan_cache_mode;

-- C) El límite sale de una subconsulta: se poda durante la ejecución
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, BUFFERS OFF, SUMMARY OFF)
SELECT count(*) FROM validaciones_mes
WHERE ts >= (SELECT max(ts) - interval '12 hours' FROM validaciones_2026_06);

