CREATE FUNCTION viajes_enrutar() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.ts >= '2026-05-01' AND NEW.ts < '2026-06-01' THEN
    INSERT INTO viajes_2026_05 VALUES (NEW.*);
  ELSIF NEW.ts >= '2026-06-01' AND NEW.ts < '2026-07-01' THEN
    INSERT INTO viajes_2026_06 VALUES (NEW.*);
  ELSE
    RAISE EXCEPTION 'No hay tabla hija para %', NEW.ts;
  END IF;
  RETURN NULL;  -- la fila no se guarda en el padre
END $$;
